function [el, error]=initEyelinkNew(subjectCode)%% Initializes eyeLink-connection, creates edf-file% and writes experimental parameters to edf-file% % 2008 by Martin Rolfsglobal visual const scr%---------------------%% define edf-filename %%---------------------%edffilename = strcat(subjectCode,'.edf');% Provide Eyelink with details about the graphics environment% and perform some initializations. The information is returned% in a structure that also contains useful defaults% and control codes (e.g. tracker state bit and Eyelink key values).el=EyelinkInitDefaults(scr.main);% Initialization of the connection with the Eyelink Gazetracker.% exit program if this fails.if ~EyelinkInit(const.TEST>0)    fprintf('Eyelink Init aborted.\n');    cleanup;  % cleanup function    return;end%   SET UP TRACKER CONFIGURATIONEyelink('command', 'calibration_type = HV9');Eyelink('command', 'link_event_filter = LEFT,RIGHT,BUTTON');Eyelink('command', 'link_sample_data  = LEFT,RIGHT,GAZE,AREA');Eyelink('command', 'heuristic_filter = 1 1');    % create edf-filei = Eyelink( 'openfile', edffilename);if i~=0	printf('Cannot create EDF file ''%s'' ', edffilename);	Eyelink( 'Shutdown');	return;end%---------------------------------------%% general information on the experiment %%---------------------------------------%Eyelink('command', 'add_file_preamble_text ''Recorded with IntrasaccadicMIPS by Martin Rolfs''');%--------------------------------------------------------%% write descriptions of the experiment into the edf-file %%--------------------------------------------------------%Eyelink('message', 'BEGIN OF DESCRIPTIONS');Eyelink('message', 'Subject code: %s', subjectCode);Eyelink('message', 'END OF DESCRIPTIONS');%--------------------------------------%% modify a few of the default settings %%--------------------------------------%el.backgroundcolour = visual.bgColor;		% background color when calibratingel.foregroundcolour = visual.fgColor;        % foreground color when calibratingel.calibrationfailedsound = 0;				% no sounds indicating success of calibrationel.calibrationsuccesssound = 0;% test mode of eyelink connectionstatus = Eyelink('isconnected');switch status    case -1        fprintf(1, 'Eyelink in dummymode.\n\n');    case  0        fprintf(1, 'Eyelink not connected.\n\n');    case  1        fprintf(1, 'Eyelink connected.\n\n');endif Eyelink('isconnected')==el.notconnected    reddUp;enderror=el.ABORT_EXPT;